66	export function plUpdate(glider: THREE.Group, s: GliderState, dt: number, turnInput?: number): void {
67	  if (OFF) return;
68	  let e = entries.get(glider);
69	  if (!e) {
70	    if (glider.userData.plOff) return;
71	    e = { rig: null, track: { x: 0, y: 0, z: 0, speed: 0, has: false }, sig: { turn: 0, acc: 0, vy: 0, wind: 0 }, seed: ++seeds };
72	    entries.set(glider, e);
73	  }
74	  if (!e.rig) {
75	    const so = need();
76	    if (!so || !glider.visible) return;
77	    attach(glider, e, so);
78	    if (!e.rig) return;
79	  }
80	  try {
81	    plSignals(e.sig, e.track, s.pos.x, s.pos.y, s.pos.z, s.bank, dt, plWind(), turnInput);
82	    e.rig!.update(e.sig, dt);
83	  } catch (err) {
84	    /* lỗi lúc diễn: trả hình khối cho dù này, không ném về vòng vẽ */
